```python
import math

def fibonacci(n):
    if n <= 0:
        return "Input should be a positive integer"
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return math.fibonacci(n-1) + math.fibonacci(n-2)

print(fibonacci(10))  # Output: 55
```

