```javascript
const AWS = require('aws-sdk');

const s3 = new AWS.S3({
  region: 'your-region',
  accessKeyId: 'your-access-key-id',
  secretAccessKey: 'your-secret-access-key'
});

const uploadFile = (file, bucket, objectKey) => {
  s3.upload({
    Bucket: bucket,
    Key: objectKey,
    Body: file
  });
};

// Upload a file to S3
uploadFile('example.txt', 'my-bucket', 'example.txt');
```

